<?php
declare(strict_types=1);require_once __DIR__.'/common.php';
if(($_SERVER['REQUEST_METHOD']??'')!=='POST')fb_out(false,'Only POST requests are allowed.',['code'=>'METHOD_NOT_ALLOWED'],405);$pdo=fb_pdo();fb_schema($pdo);$in=fb_in();$token=trim((string)($in['token']??''));$body=fb_clean($in['message']??'',10000);if($token===''||$body==='')fb_out(false,'A message is required.',['code'=>'MESSAGE_REQUIRED'],422);$ticket=fb_access($pdo,$token);if(!$ticket)fb_out(false,'Invalid support link.',['code'=>'INVALID_TICKET_LINK'],404);if((string)$ticket['status']==='closed')fb_out(false,'This support conversation is closed.',['code'=>'TICKET_CLOSED'],409);$auth=fb_authorized($pdo,$ticket);if(!$auth['ok'])fb_out(false,'This support conversation is not yet verified.',['code'=>'VERIFICATION_REQUIRED','verification_required'=>$auth['reason']],403);$u=$auth['user'];$senderId=(string)$ticket['access_type']==='guest'?null:(int)$u['user_id'];$senderName=(string)$ticket['access_type']==='guest'?$ticket['name']:(string)$u['full_names'];$senderEmail=(string)$ticket['email'];
$s=$pdo->prepare("INSERT INTO support_ticket_messages(ticket_id,sender_type,sender_id,sender_name,sender_email,body) VALUES(:t,'user',:sid,:n,:e,:b)");$s->execute([':t'=>(int)$ticket['ticket_id'],':sid'=>$senderId,':n'=>$senderName,':e'=>$senderEmail,':b'=>$body]);$pdo->prepare("UPDATE support_tickets SET status='awaiting_admin',last_user_reply_at=CURRENT_TIMESTAMP,last_message_at=CURRENT_TIMESTAMP,close_at=NULL,solved_at=NULL,closed_at=NULL,admin_last_reminder_at=NULL WHERE id=:id LIMIT 1")->execute([':id'=>(int)$ticket['ticket_id']]);fb_notify_admins($pdo,'Support reply received','Ticket LM-TKT-'.str_pad((string)$ticket['ticket_id'],6,'0',STR_PAD_LEFT).' has a new user reply and requires support attention.',(int)$ticket['ticket_id']);
$adminHtml='<div style="font-family:Arial,sans-serif;background:#f7f7fb;padding:26px"><div style="max-width:700px;margin:auto;background:#fff;border-radius:18px;padding:28px"><h2 style="color:#6d28d9">New LOVEMI Support Reply</h2><p><strong>Ticket:</strong> LM-TKT-'.str_pad((string)$ticket['ticket_id'],6,'0',STR_PAD_LEFT).'</p><p><strong>User:</strong> '.fb_esc($senderName).' &lt;'.fb_esc($senderEmail).'&gt;</p><p><strong>Subject:</strong> '.fb_esc((string)$ticket['subject']).'</p><div style="padding:18px;background:#faf9fc;border-radius:12px;line-height:1.7">'.nl2br(fb_esc($body)).'</div></div></div>';$mail=fb_mail(FB_SUPPORT_EMAIL,FB_SUPPORT_NAME,'[LOVEMI SUPPORT REPLY] LM-TKT-'.str_pad((string)$ticket['ticket_id'],6,'0',STR_PAD_LEFT).' - '.(string)$ticket['subject'],$adminHtml);
fb_out(true,'Your reply was sent to LOVEMI Support.',['mail_sent'=>$mail,'ticket_id'=>(int)$ticket['ticket_id']]);
